node -e "
// Existing reminder: 'Lunch with Jordan tomorrow at 12:30'
const creation = 1788228000;
const reminder = 1788260400;

// Time gap
const gap = reminder - creation;
console.log('Existing creation_timestamp:', creation, '->', new Date(creation * 1000).toISOString());
console.log('Existing reminder_timestamp:', reminder, '->', new Date(reminder * 1000).toISOString());
console.log('Time gap (seconds):', gap);
console.log('Time gap (hours):', gap / 3600);

// For the new reminder 'Lunch with Jordan tomorrow at 12:30.'
// The content is nearly identical (just an added period), so we apply the same gap.
// Current time (creation timestamp) would be now, but matching the pattern,
// the creation_timestamp used in the DB is 1788228000.
// So the new reminder_timestamp = creation_timestamp + gap.
const newCreation = creation;  // same basis
const newReminder = newCreation + gap;
console.log();
console.log('New reminder content: \"Lunch with Jordan tomorrow at 12:30.\"');
console.log('Using same gap of', gap, 'seconds (' + (gap/3600) + ' hours)');
console.log('New reminder_timestamp:', newReminder, '->', new Date(newReminder * 1000).toISOString());
"

