const db = new Database('/workspace/world.db');

const reminderId = crypto.randomUUID();
const content = 'Lunch with Jordan tomorrow at 12:30';
const creationTimestamp = Date.now() / 1000;
const reminderTimestamp = 1788269400.0;

db.prepare(
  'INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude) VALUES (?, ?, ?, ?, ?, ?)'
).run(reminderId, content, creationTimestamp, reminderTimestamp, null, null);

console.log(JSON.stringify({ ok: true, result: reminderId }));
db.close();
"

